snapshots.perception:
"""
Perception module for grid environment.
Produces a concise summary of all non‑background cells (including white cells)
so that the full state is recoverable and the action between consecutive states
can be uniquely identified. The summary includes the grid shape and the
background colour.
"""

import json
from collections import Counter

# No longer assume "white" is empty; all non‑background cells are listed.

def _determine_bg(grid):
    """Return the most frequent colour in the grid (the background)."""
    flat = [cell for row in grid for cell in row]
    if not flat:
        return "black"          # safe fallback
    return Counter(flat).most_common(1)[0][0]

def _parse_grid(obs: str):
    """Extract the 2D colour grid as list[list[str]]."""
    if not obs:
        return None
    start = obs.find("[[")
    end = obs.rfind("]]")
    if start == -1 or end == -1 or end < start:
        return None
    try:
        grid = json.loads(obs[start : end + 2])
    except Exception:
        return None
    if not grid or not isinstance(grid, list) or not isinstance(grid[0], list):
        return None
    return grid

def _format_cell(r, c, colour):
    """Compact representation: 'r,c:colour'."""
    return f"{r},{c}:{colour}"

def perceive(observation_history: list[str]) -> str:
    obs = observation_history[-1] if observation_history else ""
    grid = _parse_grid(obs)
    if grid is None:
        return "empty"   # never empty, never raise

    # Determine background colour
    try:
        bg = _determine_bg(grid)
    except Exception:
        bg = "black"     # safe fallback

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Collect all cells that are NOT background (including white)
    cells = []
    for r, row in enumerate(grid):
        for c, colour in enumerate(row):
            if colour != bg:
                cells.append(_format_cell(r, c, colour))

    # Sort numerically by row, then column
    cells.sort(key=lambda s: (int(s.split(',')[0]),
                              int(s.split(',')[1].split(':')[0])))

    # Build summary: bg, shape, and the list of coloured cells
    shape = f"{rows}x{cols}"
    if cells:
        summary = f"bg={bg}; shape={shape}; " + " ".join(cells)
    else:
        summary = f"bg={bg}; shape={shape}; none"

    # Final safety: ensure non‑empty and under limits
    if not summary:
        summary = "empty"
    if len(summary) > 1999:
        # Truncate only as last resort – keep the prefix and first part
        summary = summary[:1996] + "..."

    return summary
